# -*- coding: utf-8 -*-
import struct, binascii
hx = open(r"tools-temp/_tmp_flea_corpse_hex.py").read()
# use the hex from earlier run
raw = binascii.unhexlify(
""
)
# If we pad seq to 0000, layout matches templates starting at 0000000A
# Offsets in CorpseFullUpdate are relative to template starting 0000000A (no AOSharp seq)
# Our capture has C8D4 prefix - strip 2 bytes for offset compare with Filth (0000000A start)
raw2 = b"\x00\x00" + raw[2:]  # replace C8D4 with 0000
print("len", len(raw2))
# find name
name = b"Remains of Garbage Flea"
i = raw2.find(name)
print("name at", i, "NameOffset expect 231", "NameLength at", i-4, struct.unpack(">I", raw2[i-4:i]))
# MonsterScale at 143
print("scale@143", struct.unpack(">I", raw2[143:147]))
print("mesh@199", struct.unpack(">I", raw2[199:203]))
# find monsterdata 17657 = 0x44F9
md = struct.pack(">I", 17657)
print("md bytes", md.hex(), "at", raw2.find(md))
# find dead instance 79ABE9EC
di = bytes.fromhex("79ABE9EC")
print("dead inst occurrences", [n for n in range(len(raw2)) if raw2.startswith(di, n)])
# Material #9
print("Material at", raw2.find(b"Material #9"))
